{
 "title": "Suspicious PowerShell Access to SAM Hive",
 "description": "Detects PowerShell processes attempting to access the Windows SAM hive via reg save or similar commands, indicative of credential dumping.",
 "tags": [
  "attack.credential-access",
  "attack.t1003.002"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection_powershell",
   "fields": [
    {
     "field": "Image",
     "modifier": "endswith",
     "values": [
      "\\powershell.exe"
     ]
    }
   ]
  },
  {
   "name": "selection_sam_access",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "reg save HKLM\\SYSTEM"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "reg save HKLM\\SAM"
     ]
    }
   ]
  }
 ],
 "condition": "selection_powershell and selection_sam_access",
 "falsepositives": [
  "Legitimate system administration tasks involving registry backups by authorized personnel."
 ],
 "level": "high"
}

{
 "title": "Suspicious AD Find Execution",
 "description": "Detects execution of adfind.exe with command-line arguments commonly used for Active Directory enumeration.",
 "tags": [
  "attack.t1087.002",
  "attack.discovery"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "image_selection",
   "fields": [
    {
     "field": "OriginalFileName",
     "modifier": "exact",
     "values": [
      "adfind.exe"
     ]
    }
   ]
  },
  {
   "name": "cmdline_enumerate_ad",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "-gc"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "-subnets"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "-sc"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "-f"
     ]
    }
   ]
  }
 ],
 "condition": "image_selection and cmdline_enumerate_ad",
 "falsepositives": [
  "Legitimate use by administrators for troubleshooting or inventory."
 ],
 "level": "high"
}

{
 "title": "Rundll32 Execution With Uncommon DLL Extension",
 "description": "Detects the execution of rundll32 with a command line that does not contain a common DLL extension (.dll, .drv, .cpl)",
 "tags": [
  "attack.t1218.011",
  "attack.stealth"
 ],
