 "groups": [
  {
   "name": "rundll32_execution",
   "fields": [
    {
     "field": "OriginalFileName",
     "modifier": "exact",
     "values": [
      "rundll32.exe"
     ]
    }
   ]
  },
  {
   "name": "uncommon_extension",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains|all",
     "values": []
    }
   ]
  }
 ],
 "condition": "rundll32_execution and not (CommandLine contains '.dll' or CommandLine contains '.drv' or CommandLine contains '.cpl')",
