{
 "title": "Chromium Based Browser Execution With Dump-Dom",
 "description": "Detects Chromium-based browsers running in headless mode via dump-dom command line used for downloading files.",
 "tags": [
  "attack.command-and-control",
  "attack.stealth",
  "attack.t1105",
  "attack.t1564.003"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "headless_browser_dump_dom",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "--headless"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "dump-dom"
     ]
    }
   ]
  },
  {
   "name": "chromium_image",
   "fields": [
    {
     "field": "OriginalFileName",
     "modifier": "re",
     "values": [
      "chrome\\.exe$",
      "msedge\\.exe$",
      "brave\\.exe$",
      "opera\\.exe$",
      "vivaldi\\.exe$"
     ]
    }
   ]
  }
 ],
 "condition": "headless_browser_dump_dom and chromium_image",
 "falsepositives": [],
 "level": "high"
}

{
 "title": "Tampering With DisableRestrictedAdmin Registry Value",
 "description": "Detects modification of the DisableRestrictedAdmin registry value used to control Restricted Admin Mode in RDP.",
 "tags": [
  "attack.t1112",
  "attack.persistence",
  "attack.defense-impairment"
 ],
 "logsource_category": "registry_set",
 "groups": [
  {
   "name": "selection_sysmon_commandline",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "reg add"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "DisableRestrictedAdmin"
     ]
    }
   ]
  },
  {
   "name": "selection_registry_targetobject",
   "fields": [
    {
     "field": "TargetObject",
     "modifier": "endswith",
     "values": [
      "\\DisableRestrictedAdmin"
     ]
    }
   ]
  }
 ],
 "condition": "(selection_sysmon_commandline) or (selection_registry_targetobject)",
 "falsepositives": [
  "Unknown"
 ],
 "level": "high"
}

