{
 "title": "Potential Disabling of Windows Defender Firewall via Registry",
 "description": "Detects attempts to disable Windows Defender Firewall by modifying registry keys associated with firewall settings.",
 "tags": [
  "attack.t1562.004",
  "attack.defense-impairment"
 ],
 "logsource_category": "network_connection",
 "groups": [
  {
   "name": "firewall_registry_modification",
   "fields": [
    {
     "field": "Image",
     "modifier": "endswith",
     "values": [
      "reg.exe"
     ]
    },
    {
     "field": "DestinationIp",
     "modifier": "contains",
     "values": []
    }
   ]
  },
  {
   "name": "firewall_key_access",
   "fields": [
    {
     "field": "Initiated",
     "modifier": "re",
     "values": [
      "HKEY_LOCAL_MACHINE\\\\SYSTEM\\\\CurrentControlSet\\\\Services\\\\SharedAccess\\\\Parameters\\\\FirewallPolicy.*"
     ]
    }
   ]
  }
 ],
 "condition": "firewall_registry_modification and firewall_key_access",
 "falsepositives": [
  "Legitimate administrative use of reg.exe to modify firewall policies."
 ],
 "level": "high"
}
